import{_ as t,o,c as r,j as e,a as s}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/96-若你是回避型.md","filePath":"books/attached/96-若你是回避型.md","lastUpdated":1794316978000}'),n={name:"books/attached/96-若你是回避型.md"};function d(c,a,l,_,i,p){return o(),r("div",null,[...a[0]||(a[0]=[e("h3",{id:"若你是回避型",tabindex:"-1"},[s("若你是回避型 "),e("a",{class:"header-anchor",href:"#若你是回避型","aria-label":'Permalink to "若你是回避型"'},"​")],-1),e("p",null,"虽然说互相理解可以非常有效地推进两个人的关系，但是对于回避型依恋风格的人来说，有效沟通也有着独特的效用。作为一位回避型人士，你可能常常感觉自己需要保持距离和独立性，总之就是有这种诉求，也说不上来为什么。一旦开始这种想法，你就会感觉自己对伴侣丧失了兴趣，怎么描述这种感觉呢？就是在某一瞬间，觉得对方或许不是自己想要的那个人，甚至觉得长痛不如短痛。但后来你就会发现，自己辗转于失败的恋情之间，经历着一次又一次相同的戏码。作为回避型人士，在一开始的调情阶段，你就应该适时表露出自己对独立空间的要求，无论是身体上还是心理上，一旦你感到两人关系太近时，就要及时学会将对距离的诉求表达出来。你要事先向伴侣解释，当你感觉到关系有些太过粘腻时，会需要一些时间来独处，而这并不是因为双方在关系中出了什么问题，这一点非常重要。这种沟通可以有效地平复他们的焦虑，也能一定程度地安抚他们的依恋机制。了解了这些，他们就不会一门心思只想跟你接近（这是让你最难以忍受的事情）。这样一来，你和伴侣的关系也就不会一直呈现着猫抓老鼠的态势了。",-1),e("p",null,"安德烈斯（Andres）是个回避型依恋风格的人，他和莫妮卡（Monica）结婚二十五年了，开始发现自己得了一种慢性的自身免疫疾病。医生说这种病不好治愈，但不会对他的生活和寿命产生什么影响。另外，他需要定期进行检查。他已经由首次发现的震惊，转为后来就习以为常了，他已经学会将眼前的境遇摆到一边，减少对自己的困扰，继续如常生活。但莫妮卡似乎不是这样的，她并不相信“一切正常”的说辞。她总要时不时劝安德烈斯去复诊，进而对自己的身体状况进行全面的了解。但安德烈斯却总是逃避话题，还将医嘱弃之不顾，有时候，这件事就会让两人产生很大的冲突。最终，在几个月的周旋以后，他终于开始直接和莫妮卡对峙了。他当然知道，莫妮卡的出发点是担忧和顾虑，可是这种担忧毫无用处，只会一遍又一遍让他想起自己的病情。他很信任自己的医生，也觉得自己不再需要更进一步的治疗。他觉得莫妮卡的行为不仅无异于他的健康，也会损害两人的关系。莫妮卡意识到了自己的行为不能帮助到安德烈斯，这只是她处理疾病的方式，而不该强加于对方。她认识到自己应该做一位尊重并支持对方意愿的伴侣，而不是一味地强迫对方。自此以后，莫妮卡开始注重自我检讨（虽然并不总是如此），渐渐将两人的冲突缓和了下来。",-1)])])}const h=t(n,[["render",d]]);export{f as __pageData,h as default};
